def _expand_given_rows() -> list[tuple[str, str, bool]]:
    rows: list[tuple[str, str, bool]] = []
    seen: set[str] = set()
    for src, zh, need_h in _GIVEN_NAME_CORE:
        for form in (src, _hira_to_kata(src) if re.fullmatch(r"[\u3040-\u309fー]+", src) else ""):
            if not form or form in seen:
                continue
            seen.add(form)
            rows.append((form, zh, need_h))
    return rows


_GIVEN_NAME_JA_TO_ZH: list[tuple[str, str, bool]] = _expand_given_rows()

