def convert_ja_kanji_to_zh(text: str) -> str:
    """Map Japanese name/place kanji forms to Simplified Chinese characters."""
    return str(text or "").translate(_JA_TO_ZH_TABLE)


def _build_surname_pairs() -> list[tuple[str, str]]:
    pairs: list[tuple[str, str]] = []
    seen: set[str] = set()
    for src in _TOP_SURNAMES:
        if not src or src in seen:
            continue
        seen.add(src)
        tgt = _SURNAME_OVERRIDES.get(src) or convert_ja_kanji_to_zh(src)
        if tgt and tgt != src:
            pairs.append((src, tgt))
    # Explicit extras that may not be in TOP list
    for src, tgt in (
        ("渡邊", "渡边"),
        ("濱崎", "滨崎"),
        ("濱田", "滨田"),
        ("濱口", "滨口"),
        ("廣瀬", "广濑"),
        ("櫻井", "樱井"),
        ("田邊", "田边"),
        ("霧島", "雾岛"),
        ("西園寺", "西园寺"),
        ("二階堂", "二阶堂"),
        ("四宮", "四宫"),
        ("穂積", "穗积"),
        ("亀井", "龟井"),
        ("竜崎", "龙崎"),
    ):
        if src not in seen and src != tgt:
            pairs.append((src, tgt))
            seen.add(src)
    pairs.sort(key=lambda r: -len(r[0]))
    return pairs


_SURNAME_JA_TO_ZH: list[tuple[str, str]] = _build_surname_pairs()


def surname_mt_entries() -> list[dict[str, str]]:
    """MT glossary rows for common surnames (JA orthography → 简体 + 敬称)."""
    rows: list[dict[str, str]] = []
    seen: set[str] = set()
    honor_mt = (
        ("ちゃん", "酱"),
        ("さん", "桑"),
        ("くん", "君"),
        ("君", "君"),
        ("様", "大人"),
    )

    def _add(src: str, tgt: str) -> None:
        if not src or not tgt or src == tgt or src in seen:
            return
        seen.add(src)
        rows.append({"src": src, "tgt": tgt, "stage": "mt"})

    for s, t in _SURNAME_JA_TO_ZH:
        _add(s, t)
        for h_ja, h_zh in honor_mt:
            _add(f"{s}{h_ja}", f"{t}{h_zh}")
    return rows


def given_name_mt_entries(*, honorific_only_safe: bool = True) -> list[dict[str, str]]:
    """
    MT glossary rows for common given names.

    Keep expansions lean (さん/ちゃん/くん/様 + 彼女の/彼の) so cue protect
    stays fast; vocative prefixes are handled in polish_ja_names_zh.
    Honorifics restore as 桑/酱/君/大人 (not bare name).
    """
    rows: list[dict[str, str]] = []
    seen: set[str] = set()
    honor_mt = (
        ("ちゃん", "酱"),
        ("さん", "桑"),
        ("くん", "君"),
        ("君", "君"),
        ("様", "大人"),
    )

    def _add(src: str, tgt: str) -> None:
        if not src or not tgt or src == tgt or src in seen:
            return
        seen.add(src)
        rows.append({"src": src, "tgt": tgt, "stage": "mt"})

    for kana, zh, need_h in _GIVEN_NAME_JA_TO_ZH:
        if need_h and honorific_only_safe:
            for h_ja, h_zh in honor_mt:
                _add(f"{kana}{h_ja}", f"{zh}{h_zh}")
            _add(f"彼女の{kana}", f"她是{zh}")
            _add(f"彼の{kana}", f"他是{zh}")
            continue
        _add(kana, zh)
        for h_ja, h_zh in honor_mt:
            _add(f"{kana}{h_ja}", f"{zh}{h_zh}")
        _add(f"彼女の{kana}", f"她是{zh}")
        _add(f"彼の{kana}", f"他是{zh}")
    return rows


def builtin_ja_name_mt_glossary() -> list[dict[str, str]]:
    """All built-in JA→ZH name glossary rows for dual/translate_mt."""
    return surname_mt_entries() + given_name_mt_entries(honorific_only_safe=True)


def asr_name_variant_entries() -> list[dict[str, str]]:
    """
    Common ASR orthography normalizations (same-language).

    Prefer hiragana / canonical kanji for frequent cast given names;
    katakana→hiragana for names that usually appear in kana dialogue.
    """
    rows: list[dict[str, str]] = []
    seen: set[str] = set()

    def _add(wrong: str, correct: str) -> None:
        if not wrong or not correct or wrong == correct or wrong in seen:
            return
        seen.add(wrong)
        rows.append({"wrong": wrong, "correct": correct, "stage": "asr"})

    # High-value Whisper mishears / script variants
    for wrong, correct in (
        ("マイ", "舞"),
        ("まい", "舞"),
        ("彼女の前", "彼女の舞"),  # soft JA: 舞 misheard as 前
        ("彼女のまえ", "彼女の舞"),
        ("あっかりさん", "あかりさん"),
        ("あっかり", "あかり"),
        ("アカリ", "あかり"),
        ("アッカーリ", "あかり"),
        ("モモコ", "桃子"),
        ("ももこ", "桃子"),
        ("マヒロ", "まひろ"),
        ("トミー", "トミー"),
        ("とみ", "トミー"),
        ("トミ", "トミー"),
        ("とみー", "トミー"),
        # 舞 bias / まい→舞 can corrupt うまい → う舞
        ("う舞ねえ", "うんねえ"),
        ("う舞ねぇ", "うんねぇ"),
        ("うまいねえっ", "うんねえっ"),  # う舞→うまい over-correction on vocative
        ("うまいねえ", "うんねえ"),
        ("うまいねぇ", "うんねぇ"),
        ("う舞", "うまい"),
        ("どういえ", "どういたしまして"),
    ):
        _add(wrong, correct)

    # Katakana → hiragana for all core kana given names (dialogue consistency)
    for src, _zh, _need in _GIVEN_NAME_CORE:
        if not re.fullmatch(r"[\u3040-\u309fー]+", src or ""):
            continue
        kata = _hira_to_kata(src)
        _add(kata, src)

    return rows


def common_ja_given_names_for_bias(limit: int = 40) -> list[str]:
    """
    Compact cast-name list for Whisper initial_prompt when user omitted castNames.

    Prefer distinctive (non-honorific-gated) readings; capped to avoid prompt bloat.
    """
    out: list[str] = []
    seen: set[str] = set()
    # High-priority AV cast forms first (FNS-style 舞 / トミー / HMN-style さつき)
    for form in ("舞", "トミー", "マイ", "まい", "さつき", "サツキ"):
        if form not in seen:
            seen.add(form)
            out.append(form)
    for src, zh, need_h in _GIVEN_NAME_CORE:
        if need_h:
            continue
        # Prefer Chinese/kanji lock form when available, else hiragana
        form = zh if re.search(r"[\u4e00-\u9fff]", zh) else src
        if form in seen or len(form) > 4:
            continue
        seen.add(form)
        out.append(form)
        if len(out) >= limit:
            break
    return out[:limit]


def ja_whisper_name_bias(
    *,
    cast_names: Any = None,
    limit: int = 24,
) -> tuple[str, str]:
    """
    Strong Whisper initial_prompt + hotwords for JA dialogue names.

    Always biases 舞/トミー (+ kana variants) then other common given names /
    user castNames. Returns (prompt, hotwords) or ("", "") if disabled empty.
    """
    labels: list[str] = []
    hot: list[str] = []
    seen: set[str] = set()

    def _push(label: str, *forms: str) -> None:
        lab = str(label or "").strip()
        if not lab or lab in seen:
            return
        seen.add(lab)
        labels.append(lab)
        for f in forms:
            ff = str(f or "").strip()
            if ff and ff not in hot:
                hot.append(ff)

    # Priority cast (mishears → canonical)
    _push("舞（マイ）", "舞", "マイ", "まい")
    _push("トミー", "トミー", "とみ", "トミ", "トミー")
    _push("さつき", "さつき", "サツキ")

    if isinstance(cast_names, (list, tuple)):
        for item in cast_names:
            name = str(item or "").strip()
            if name:
                _push(name, name)

    for form in common_ja_given_names_for_bias(limit):
        if form in ("舞", "トミー", "マイ", "まい", "さつき", "サツキ"):
            continue
        _push(form, form)
        if len(labels) >= limit:
            break

    if not labels:
        return "", ""
    # Keep prompt short — didactic 「舞は人名です」leaks into ASR (HMN-878).
    prompt = "登場人物：" + "、".join(labels) + "。"
    return prompt, " ".join(hot)


def polish_ja_names_zh(src_ja: str, zh: str) -> str:
    """
    Post-MT: convert leftover JA kanji forms; force given-name 译名 when
    source shows clear name context (honorific / 彼女の…).
    """
    src = str(src_ja or "")
    out = convert_ja_kanji_to_zh(str(zh or ""))
    if not src.strip() or not out:
        return out

    for ja, zh_name in _SURNAME_JA_TO_ZH:
        if ja in src:
            out = out.replace(ja, zh_name)

    for kana, zh_name, need_h in _GIVEN_NAME_JA_TO_ZH:
        if kana not in src:
            continue
        honor = any(f"{kana}{h}" in src for h in _HONOR)
        prefix = any(f"{p}{kana}" in src for p in _NAME_PREFIX)
        if need_h and not (honor or prefix):
            continue
        if kana in out:
            out = out.replace(kana, zh_name)
        if re.fullmatch(rf"{re.escape(kana)}です。?", src.strip()):
            out = f"我是{zh_name}。"
        # Introduction cue「彼女のX」/「彼のX」→ 她是/他是 (not possessive 她的/他的)
        if src.strip() in {f"彼女の{kana}", f"彼女の{kana}。"}:
            out = f"她是{zh_name}"
        if src.strip() in {f"彼の{kana}", f"彼の{kana}。"}:
            out = f"他是{zh_name}"

    return out


def merge_name_glossary(existing: Any) -> list[Any]:
    """Prepend built-in name MT rows; later normalize_glossary lets user win on src."""
    builtin = builtin_ja_name_mt_glossary()
    if not existing:
        return list(builtin)
    if isinstance(existing, list):
        return list(builtin) + list(existing)
    return list(builtin) + [existing]


def merge_asr_name_glossary(existing: Any) -> list[Any]:
    """Built-in ASR name variants first; user entries last (override)."""
    builtin = asr_name_variant_entries()
    if not existing:
        return list(builtin)
    if isinstance(existing, list):
        return list(builtin) + list(existing)
    return list(builtin) + [existing]


def lexicon_stats() -> dict[str, int]:
    """Counts for tests / diagnostics."""
    return {
        "surnamePairs": len(_SURNAME_JA_TO_ZH),
        "givenCore": len(_GIVEN_NAME_CORE),
        "givenExpanded": len(_GIVEN_NAME_JA_TO_ZH),
        "mtRows": len(builtin_ja_name_mt_glossary()),
        "asrRows": len(asr_name_variant_entries()),
        "kanjiMap": len(_JA_KANJI_TO_ZH),
    }
